INSERT INTO ranking_tables.track_ranking (id, track_id, decade_genre_id, tracklist_id, ranking, intro, ranking_date) VALUES (168, 164, 5, 1, 34, 'Unleash the drama with ''Breaking Bad'', the 34th ranked track of the 2000s, composed by Dave Porter from the album Breaking Bad: Original Score from the Television Series. A must-hear in TV Themes!', '2025-07-25');
INSERT INTO ranking_tables.track_ranking (id, track_id, decade_genre_id, tracklist_id, ranking, intro, ranking_date) VALUES (169, 165, 5, 1, 35, 'Step back in time with ''Mad Men'', ranked 35th in the 2000s, brought to life by RJD2 from the album A Beautiful Mine (Mad Men Instrumental Theme) [From "Retrospective: The Music Of Mad M].', '2025-07-25');
INSERT INTO ranking_tables.track_ranking (id, track_id, decade_genre_id, tracklist_id, ranking, intro, ranking_date) VALUES (170, 166, 5, 1, 36, 'Sink your teeth into ''True Blood'', the 36th ranked TV theme of the 2000s, sung by Jace Everett from the album TRUE BLOOD (Music from the HBO® Original Series). A haunting melody!', '2025-07-25');
INSERT INTO ranking_tables.track_ranking (id, track_id, decade_genre_id, tracklist_id, ranking, intro, ranking_date) VALUES (171, 167, 5, 1, 37, 'Get a taste of suspense with ''Dexter'', ranked 37th in the 2000s TV Themes, crafted by Rolfe Kent from the album Dexter Season 4. It''s chillingly good!', '2025-07-25');
INSERT INTO ranking_tables.track_ranking (id, track_id, decade_genre_id, tracklist_id, ranking, intro, ranking_date) VALUES (172, 168, 5, 1, 38, 'Discover the quirky charm of ''Weeds'', the 38th ranked track from the 2000s, sung by Malvina Reynolds from the album Weeds (Music from the Original Series). A unique TV theme!', '2025-07-25');
